/* Readscope bar: Products dropdown. Generated by build.js, do not edit. */
(function(){
  var bar=document.querySelector('[data-rsn]');if(!bar)return;
  var btn=bar.querySelector('[data-rsn-toggle]'),panel=document.getElementById('rsn-menu');if(!btn||!panel)return;
  function set(open){btn.setAttribute('aria-expanded',open?'true':'false');panel.hidden=!open;}
  btn.addEventListener('click',function(e){e.stopPropagation();set(panel.hidden);});
  document.addEventListener('click',function(e){if(!panel.hidden&&!panel.contains(e.target))set(false);});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!panel.hidden){set(false);btn.focus();}});
})();
